function diagnose({ workflow, execution }) {
  if (!workflow || !Array.isArray(workflow.nodes)) {
    throw new Error("workflow.nodes must be an array");
  }
  if (!execution || typeof execution !== "object" || Array.isArray(execution)) {
    throw new Error("execution must be an object");
  }

  const nodeTypes = new Map(
    workflow.nodes.map((node) => [String(node.name || ""), String(node.type || "")]),
  );
  const data = execution.data && typeof execution.data === "object" ? execution.data : {};
  const result =
    data.resultData && typeof data.resultData === "object"
      ? data.resultData
      : execution.resultData && typeof execution.resultData === "object"
        ? execution.resultData
        : {};
  const lastNode = result.lastNodeExecuted ? String(result.lastNodeExecuted) : null;
  const runData = result.runData && typeof result.runData === "object" ? result.runData : {};
  const failures = [];
  function safeMessage(value) {
    let text = String(value ?? "")
      .replace(/\s+/g, " ")
      .trim();
    text = text.replace(/bearer\s+[A-Za-z0-9._~+/-]{8,}/gi, "Bearer [REDACTED]");
    text = text.replace(
      /(api[_-]?key|token|secret|password|authorization)\s*[:=]\s*(?:bearer\s+)?[^\s,;}]+/gi,
      "$1=[REDACTED]",
    );
    return text.slice(0, 300);
  }

  function classify(message, status) {
    const text = `${String(status ?? "")} ${message}`.toLowerCase();
    if (
      ["401", "403", "unauthorized", "forbidden", "credential", "authentication"].some((x) =>
        text.includes(x),
      )
    ) {
      return [
        "authentication",
        "Verify credential reference, auth scheme, token scope and expiry; then retest only the failing node.",
      ];
    }
    if (["429", "rate limit", "too many requests"].some((x) => text.includes(x))) {
      return [
        "rate_limit",
        "Add bounded retry with exponential backoff and respect Retry-After or the upstream rate-limit policy.",
      ];
    }
    if (["timeout", "timed out", "etimedout", "econnaborted"].some((x) => text.includes(x))) {
      return [
        "timeout",
        "Set an explicit timeout, retry only idempotent work, and isolate the slow external call from the main path.",
      ];
    }
    if (
      ["econn", "dns", "network", "connection refused", "socket hang up"].some((x) =>
        text.includes(x),
      )
    ) {
      return [
        "network",
        "Check endpoint reachability, DNS and TLS first; then add bounded retries and an explicit failure path.",
      ];
    }
    if (["400", "422", "invalid", "validation", "bad request"].some((x) => text.includes(x))) {
      return [
        "invalid_input",
        "Inspect the outbound payload/schema and validate required fields before the failing node.",
      ];
    }
    if (
      ["expression", "undefined", "cannot read", "not defined", "item linking"].some((x) =>
        text.includes(x),
      )
    ) {
      return [
        "expression",
        "Validate referenced fields, item linking and optional values before evaluating the expression.",
      ];
    }
    return [
      "execution_error",
      "Reproduce the failing node with the same sanitized input, then add an explicit error path before re-enabling automation.",
    ];
  }

  function addFailure(node, rawError) {
    const error = rawError && typeof rawError === "object" ? rawError : {};
    const rawMessage =
      error.message || error.description || error.name || rawError || "Execution failed";
    const statusCode = error.httpCode ?? error.statusCode ?? error.status ?? null;
    const message = safeMessage(rawMessage);
    const [category, recommendedNextStep] = classify(message, statusCode);
    failures.push({
      node,
      nodeType: node ? nodeTypes.get(String(node)) || null : null,
      category,
      statusCode,
      message,
      recommendedNextStep,
    });
  }
  for (const [nodeName, runs] of Object.entries(runData)) {
    if (!Array.isArray(runs)) continue;
    for (const run of runs) {
      if (!run || typeof run !== "object" || !run.error) continue;
      addFailure(nodeName, run.error);
    }
  }
  if (result.error && failures.length === 0) {
    addFailure(lastNode, result.error);
  }

  const counts = {};
  for (const failure of failures) {
    counts[failure.category] = (counts[failure.category] || 0) + 1;
  }
  const primaryCategory = Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || "unknown";

  return {
    workflowName: String(workflow.name || ""),
    lastNodeExecuted: lastNode,
    failureCount: failures.length,
    primaryCategory,
    failures,
    diagnosticStatus: failures.length ? "FAILED_EXECUTION_ANALYZED" : "NO_STRUCTURED_ERROR_FOUND",
    privacyNote: "Common secret-like strings are redacted and error messages are truncated.",
  };
}

return [{ json: diagnose($input.first().json) }];
